#!/usr/bin/env python3
"""Generate parity harness registries from API parity specs."""

from __future__ import annotations

import json
from pathlib import Path

from spec_loader import load_api_tests

HARNESS = Path(__file__).resolve().parent
RUST_OUT = HARNESS / "native" / "src" / "generated_tests.rs"
LUA_OUT = HARNESS / "fixtures" / "game.sdd" / "LuaRules" / "Utilities" / "generated_api_tests.lua"


def write_rust(tests: list[dict]) -> None:
    lines = [
        "// Generated by test/native_api_parity/generate_from_spec.py.",
        "// Edit api_tests/*.json instead.",
        "",
        "native_tests! {",
    ]
    for test in tests:
        test_id = test["id"]
        rust = test.get("rust", {})
        check = rust.get("check")
        set_handler = rust.get("set", "set_noop")
        if not check:
            raise ValueError(f"{test_id} is missing rust.check")
        lines.append(f"    {test_id} {{ check = {check}, set = {set_handler}, }}")
    lines.append("}")
    RUST_OUT.write_text("\n".join(lines) + "\n", encoding="utf-8")


def lua_literal(value) -> str:
    if isinstance(value, str):
        return json.dumps(value)
    if isinstance(value, bool):
        return "true" if value else "false"
    if value is None:
        return "nil"
    if isinstance(value, list):
        return "{" + ", ".join(lua_literal(item) for item in value) + "}"
    if isinstance(value, dict):
        parts = []
        for key, item in value.items():
            parts.append(f"[{json.dumps(str(key))}] = {lua_literal(item)}")
        return "{" + ", ".join(parts) + "}"
    return str(value)


def lua_table_rows(rows: list[dict]) -> str:
    rendered = ["return {"]
    for row in rows:
        rendered.append(f"\t{lua_literal(row)},")
    rendered.append("}")
    return "\n".join(rendered)


def write_lua(tests: list[dict]) -> None:
    rows = []
    for test in tests:
        rows.append({
            "id": test["id"],
            "context": test.get("context", "synced_gadget"),
            "kind": test.get("kind", "readonly"),
            "requires_rendering": bool(test.get("requires_rendering", False)),
            "requires": test.get("requires", []),
            "lua": test.get("lua", {}),
            "native": test.get("native", {}),
            "params": test.get("params", {}),
            "lua_runtime": test.get("lua_runtime"),
            "compare": test.get("compare", {}),
            "order_insensitive_fields": test.get("order_insensitive_fields", []),
        })

    lines = [
        "-- Generated by test/native_api_parity/generate_from_spec.py.",
        "-- Edit api_tests/*.json instead.",
        lua_table_rows(rows),
    ]
    LUA_OUT.write_text("\n".join(lines) + "\n", encoding="utf-8")


def main() -> int:
    tests = load_api_tests()
    write_rust(tests)
    write_lua(tests)
    print(f"generated {len(tests)} parity test entries")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
